input.proposed_solution:
Rename the field in the Config typedef and loadConfig(), and update every reader of it (src/http.js) plus the two unit tests. Env var API_TIMEOUT_MS is unchanged. Pure rename, no behavior change.

Patch (already applied in the repository snapshot):
```diff
--- a/src/config.js
+++ b/src/config.js
@@ -1,6 +1,6 @@
 // @ts-check

-/** @typedef {{ baseUrl: string, timeoutMs: number, retries: number }} Config */
+/** @typedef {{ baseUrl: string, requestTimeoutMs: number, retries: number }} Config */

 /**
  * @param {Record<string, string | undefined>} env
@@ -9,7 +9,7 @@
 export function loadConfig(env) {
   return {
     baseUrl: env.API_BASE_URL ?? "http://localhost:8080",
-    timeoutMs: Number(env.API_TIMEOUT_MS ?? 5000),
+    requestTimeoutMs: Number(env.API_TIMEOUT_MS ?? 5000),
     retries: Number(env.API_RETRIES ?? 2),
   };
 }
--- a/src/http.js
+++ b/src/http.js
@@ -5,5 +5,5 @@
  * @param {string} path
  */
 export function requestOptions(config, path) {
-  return { url: `${config.baseUrl}${path}`, timeout: config.timeoutMs, retries: config.retries };
+  return { url: `${config.baseUrl}${path}`, timeout: config.requestTimeoutMs, retries: config.retries };
 }
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -5,5 +5,5 @@
 test("defaults", () => {
   const c = loadConfig({});
   assert.equal(c.baseUrl, "http://localhost:8080");
-  assert.equal(c.timeoutMs, 5000);
+  assert.equal(c.requestTimeoutMs, 5000);
 });
--- a/test/http.test.js
+++ b/test/http.test.js
@@ -3,6 +3,6 @@
 import { requestOptions } from "../src/http.js";

 test("request options", () => {
-  const o = requestOptions({ baseUrl: "http://x", timeoutMs: 100, retries: 1 }, "/a");
+  const o = requestOptions({ baseUrl: "http://x", requestTimeoutMs: 100, retries: 1 }, "/a");
   assert.deepEqual(o, { url: "http://x/a", timeout: 100, retries: 1 });
 });
```
